import { SelectionFrame } from "@/components/custom/blocks/SelectionFrameBlock";

export default function LineStyles() {
  return (
    <div className="grid grid-cols-2 gap-12">
      {/* solid is the default */}
      <SelectionFrame line="solid" padding={6}>
        <span className="text-[28px] font-semibold">Lines</span>
      </SelectionFrame>

      {/* dash [4, 4] */}
      <SelectionFrame line="dashed" padding={6}>
        <span className="text-[28px] font-semibold">Lines</span>
      </SelectionFrame>

      {/* dash [10, 6] */}
      <SelectionFrame line="long" padding={6}>
        <span className="text-[28px] font-semibold">Lines</span>
      </SelectionFrame>

      {/* override either preset's dash pattern directly */}
      <SelectionFrame line="dashed" dash={[1, 3]} padding={6}>
        <span className="text-[28px] font-semibold">Lines</span>
      </SelectionFrame>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import React, { useLayoutEffect, useRef, useState } from "react";
import { springLinear } from "./motion-curves";

export type FrameHandles = "square" | "circle";
export type FrameLine = "solid" | "dashed" | "long";

export interface SelectionFrameProps {
  /** The content to frame — measured live, so it can change size freely. */
  children: React.ReactNode;
  /** Corner handle shape. Default "square". */
  handles?: FrameHandles;
  /** Stroke style. Default "solid". "dashed" and "long" both march when animated. */
  line?: FrameLine;
  /** Override the [dash, gap] px pair a non-solid `line` resolves to. */
  dash?: [number, number];
  /** Marching ants — only applies to "dashed" / "long" lines. Handles always pop in. Default false. */
  animated?: boolean;
  /** Accent colour. Default primary theme color. */
  color?: string;
  /** Frame corner radius. Default 0. */
  radius?: number;
  /** Gap between the content and the frame. Default 4. */
  padding?: number;
  /** Render inline (for text spans) instead of block. Default true. */
  inline?: boolean;
  className?: string;
}

const STROKE = 1.5;

const LINE_DASH: Record<FrameLine, [number, number] | undefined> = {
  solid: undefined,
  dashed: [4, 4],
  long: [10, 6],
};

/** Handle pop-in: a stiffness 600 / damping 24 spring, as a CSS easing. */
const HANDLE_SPRING = springLinear({ stiffness: 600, damping: 24 }, 120);

// Plain CSS. Both loops sit behind prefers-reduced-motion: the march is an
// indefinite loop, and the handles then simply start in place.
const KEYFRAMES = `
@keyframes selection-frame-march {
  from { stroke-dashoffset: 0px; }
  to { stroke-dashoffset: calc(var(--selection-frame-period) * -1); }
}
@keyframes selection-frame-handle {
  from { opacity: 0; transform: scale(0); }
  to { opacity: 1; transform: scale(1); }
}
@media (prefers-reduced-motion: no-preference) {
  .selection-frame-march { animation: selection-frame-march 1s linear infinite; }
  .selection-frame-handle { animation: selection-frame-handle ${HANDLE_SPRING.duration}ms ${HANDLE_SPRING.easing} backwards; }
}`;

export function SelectionFrame({
  children,
  handles = "square",
  line = "solid",
  dash,
  animated = false,
  color = "var(--primary, #0d99ff)",
  radius = 0,
  padding = 4,
  inline = true,
  className,
}: SelectionFrameProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const [size, setSize] = useState({ w: 0, h: 0 });

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const ro = new ResizeObserver(() => setSize({ w: el.offsetWidth, h: el.offsetHeight }));
    ro.observe(el);
    setSize({ w: el.offsetWidth, h: el.offsetHeight });
    return () => ro.disconnect();
  }, []);

  // The frame box sits `padding` outside the content, stroke centred on its edge.
  const fw = size.w + padding * 2;
  const fh = size.h + padding * 2;
  const resolvedDash = dash ?? LINE_DASH[line];
  const period = resolvedDash ? resolvedDash[0] + resolvedDash[1] : 0;

  // Marching ants need a dash pattern, so `animated` with a solid stroke is
  // just a static frame with animated corner handles. Reduced motion disables
  // both (in the stylesheet above), since the march is an indefinite loop.
  const marching = animated && !!resolvedDash;
  const animateHandles = animated;

  // The rect is drawn inset by STROKE/2 so its stroke centres inside the SVG
  // box — its visible corner tip is at (STROKE/2, STROKE/2), not (0, 0). Place
  // the handles on those centreline corners; using the box corners instead
  // leaves every handle 0.75px diagonally outward from the tip it marks.
  const half = STROKE / 2;
  const corners: Array<[string, number, number]> = [
    ["tl", half, half],
    ["tr", fw - half, half],
    ["bl", half, fh - half],
    ["br", fw - half, fh - half],
  ];

  const handleSize = handles === "circle" ? 8 : 7;

  return (
    <span
      className={cn("relative", inline ? "inline-block" : "block", className)}
      style={{ lineHeight: inline ? undefined : 0 }}
    >
      <span ref={ref} className={cn(inline ? "inline-block" : "block")}>
        {children}
      </span>

      {fw > 0 && (
        <>
          {/* frame */}
          <svg
            className="absolute pointer-events-none overflow-visible"
            width={fw}
            height={fh}
            style={{ left: -padding, top: -padding }}
            aria-hidden
          >
            <rect
              x={STROKE / 2}
              y={STROKE / 2}
              width={Math.max(0, fw - STROKE)}
              height={Math.max(0, fh - STROKE)}
              rx={radius}
              fill="none"
              stroke={color}
              strokeWidth={STROKE}
              strokeDasharray={resolvedDash ? `${resolvedDash[0]} ${resolvedDash[1]}` : undefined}
              {...(marching
                ? {
                    className: "selection-frame-march",
                    style: {
                      "--selection-frame-period": `${period}px`,
                      animationDuration: `${period * 0.075}s`,
                    } as React.CSSProperties,
                  }
                : {})}
            />
          </svg>

          {/* Corner handles. boxSizing: border-box is what keeps these centred on
              their corner point: without it the border adds outside the declared
              width/height, so the -handleSize/2 margin offset undershoots and the
              handle renders visibly off-centre from the true corner. */}
          {corners.map(([key, cx, cy], i) => (
            <FrameHandle
              key={key}
              pop={animateHandles}
              delay={0.28 + i * 0.05}
              style={{
                left: cx - padding,
                top: cy - padding,
                width: handleSize,
                height: handleSize,
                marginLeft: -handleSize / 2,
                marginTop: -handleSize / 2,
                boxSizing: "border-box",
                border: `${STROKE}px solid ${color}`,
                borderRadius: handles === "circle" ? "9999px" : 1,
                boxShadow: "0 1px 2px rgba(0,0,0,0.12)",
              }}
            />
          ))}
        </>
      )}
      <style>{KEYFRAMES}</style>
    </span>
  );
}

/**
 * One corner handle. Whether it pops in is settled when it mounts: switching
 * `animated` on later leaves a handle that is already on screen in place.
 */
function FrameHandle({
  pop,
  delay,
  style,
}: {
  pop: boolean;
  /** Seconds. */
  delay: number;
  style: React.CSSProperties;
}) {
  const [popIn] = useState(pop);
  return (
    <span
      aria-hidden
      className={cn(
        "absolute pointer-events-none bg-background",
        popIn && "selection-frame-handle",
      )}
      style={{ animationDelay: popIn ? `${delay}s` : undefined, ...style }}
    />
  );
}

/**
 * Motion curves with no animation library behind them.
 *
 * The components here ship as CSS, GSAP or Motion builds that must move
 * identically, so the curves are computed once, from the same numbers, and
 * handed to whichever engine runs them:
 *
 *   - `cubicBezier(x1, y1, x2, y2)` → an easing function (GSAP accepts any
 *     `(progress) => value` as `ease`), exact for Motion's `ease: [..]` arrays
 *     and for CSS `cubic-bezier()`.
 *   - `spring({ stiffness, damping, mass })` → the analytic solution Motion
 *     Motion uses, as an easing function plus the time it takes to settle, or
 *     as a CSS `linear()` string for a fixed start and end.
 *   - `createSpringFollower` → a value that chases a moving target through the
 *     same spring every frame, like Motion's `useSpring`, for pointer-driven
 *     motion that no fixed curve can describe.
 */

// ---------------------------------------------------------------------------
// Cubic bezier
// ---------------------------------------------------------------------------

/**
 * The CSS / Motion cubic-bezier as a function of progress. Newton-Raphson
 * with a bisection fallback, the same solver browsers use.
 */
export function cubicBezier(x1: number, y1: number, x2: number, y2: number) {
  if (x1 === y1 && x2 === y2) return (t: number) => t;

  const a = (p1: number, p2: number) => 1 - 3 * p2 + 3 * p1;
  const b = (p1: number, p2: number) => 3 * p2 - 6 * p1;
  const c = (p1: number) => 3 * p1;
  const at = (t: number, p1: number, p2: number) =>
    ((a(p1, p2) * t + b(p1, p2)) * t + c(p1)) * t;
  const slope = (t: number, p1: number, p2: number) =>
    3 * a(p1, p2) * t * t + 2 * b(p1, p2) * t + c(p1);

  const solveX = (x: number) => {
    let t = x;
    for (let i = 0; i < 8; i++) {
      const s = slope(t, x1, x2);
      if (Math.abs(s) < 1e-6) break;
      const err = at(t, x1, x2) - x;
      if (Math.abs(err) < 1e-7) return t;
      t -= err / s;
    }
    let lo = 0;
    let hi = 1;
    t = x;
    for (let i = 0; i < 30 && hi - lo > 1e-7; i++) {
      const value = at(t, x1, x2);
      if (value < x) lo = t;
      else hi = t;
      t = (lo + hi) / 2;
    }
    return t;
  };

  return (x: number) => (x <= 0 ? 0 : x >= 1 ? 1 : at(solveX(x), y1, y2));
}

/** Motion's named eases, as the cubic-beziers they are. */
export const MOTION_EASE = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
  circIn: [0.55, 0, 1, 0.45],
  circOut: [0.55, 0, 0.45, 1],
  circInOut: [0.85, 0, 0.15, 1],
  backIn: [0.31, 0.01, 0.66, -0.59],
  backOut: [0.33, 1.53, 0.69, 0.99],
  anticipate: [0.66, -0.56, 0.34, 1.35],
} as const;

/**
 * Motion's default layout transition (`layout` / `layoutId`):
 * `{ duration: 0.45, ease: [0.4, 0, 0.1, 1] }`.
 */
export const LAYOUT_TRANSITION = { duration: 0.45, ease: [0.4, 0, 0.1, 1] as const };

// ---------------------------------------------------------------------------
// Spring
// ---------------------------------------------------------------------------

export interface SpringOptions {
  /** Motion default 100. */
  stiffness?: number;
  /** Motion default 10. */
  damping?: number;
  /** Motion default 1. */
  mass?: number;
  /** Starting velocity, in units of the whole distance per second. */
  velocity?: number;
  /** How close to the end counts as settled, as a fraction of the distance. */
  restDelta?: number;
}

/**
 * Normalised position (0 → 1) of a spring released from 0 towards 1, at time
 * `t` seconds. The closed-form solution Motion's `spring()` generator
 * uses for the under-, critically and over-damped cases.
 */
export function springAt(options: SpringOptions = {}) {
  const { stiffness = 100, damping = 10, mass = 1, velocity = 0 } = options;
  const zeta = damping / (2 * Math.sqrt(stiffness * mass));
  const omega0 = Math.sqrt(stiffness / mass);
  // Motion's convention: distance still to cover, velocity toward it negated.
  const delta = 1;
  const v0 = -velocity;

  if (zeta < 1) {
    const omegaD = omega0 * Math.sqrt(1 - zeta * zeta);
    return (t: number) => {
      const envelope = Math.exp(-zeta * omega0 * t);
      return (
        1 -
        envelope *
          (((v0 + zeta * omega0 * delta) / omegaD) * Math.sin(omegaD * t) +
            delta * Math.cos(omegaD * t))
      );
    };
  }
  if (zeta === 1) {
    return (t: number) => 1 - Math.exp(-omega0 * t) * (delta + (v0 + omega0 * delta) * t);
  }
  const omegaD = omega0 * Math.sqrt(zeta * zeta - 1);
  return (t: number) => {
    const envelope = Math.exp(-zeta * omega0 * t);
    const freq = Math.min(omegaD * t, 300);
    return (
      1 -
      (envelope *
        ((v0 + zeta * omega0 * delta) * Math.sinh(freq) + omegaD * delta * Math.cosh(freq))) /
        omegaD
    );
  };
}

/** Seconds until the spring stays within `restDelta` of its end. */
export function springDuration(options: SpringOptions = {}) {
  const at = springAt(options);
  const restDelta = options.restDelta ?? 0.001;
  const step = 1 / 240;
  let lastOutside = 0;
  for (let t = 0; t <= 10; t += step) {
    if (Math.abs(1 - at(t)) > restDelta) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.max(lastOutside + step, step);
}

/**
 * A spring as a duration and an easing function over it — what GSAP takes:
 *
 *   const { duration, ease } = springEase({ stiffness: 300, damping: 20 });
 *   gsap.to(el, { y: 0, duration, ease });
 *
 * Exact for a fixed start and end; a spring that has to react mid-flight to a
 * new target needs `createSpringFollower` instead.
 */
export function springEase(options: SpringOptions = {}) {
  const duration = springDuration(options);
  const at = springAt(options);
  return {
    duration,
    ease: (progress: number) => (progress >= 1 ? 1 : at(progress * duration)),
  };
}

/**
 * A spring as a CSS `linear()` easing and its duration in ms, for
 * `transition` / `animation` with a fixed start and end.
 *
 *   const { easing, duration } = springLinear({ stiffness: 400, damping: 30 });
 *   el.style.transition = `transform ${duration}ms ${easing}`;
 */
export function springLinear(options: SpringOptions = {}, pointsPerSecond = 60) {
  const duration = springDuration(options);
  const at = springAt(options);
  const count = Math.max(Math.ceil(duration * pointsPerSecond), 8);
  const points: string[] = [];
  for (let i = 0; i <= count; i++) {
    const t = (i / count) * duration;
    points.push(String(Math.round((i === count ? 1 : at(t)) * 10000) / 10000));
  }
  return { easing: `linear(${points.join(", ")})`, duration: Math.round(duration * 1000) };
}

// ---------------------------------------------------------------------------
// Spring follower (useSpring equivalent)
// ---------------------------------------------------------------------------

/** Something that calls back once per frame with the time since the last, in ms. */
export interface FrameTicker {
  add: (callback: (deltaMs: number) => void) => () => void;
}

/** requestAnimationFrame as a ticker — the library-free default. */
export const rafTicker: FrameTicker = {
  add(callback) {
    let last = performance.now();
    let frame = requestAnimationFrame(function tick(now) {
      callback(now - last);
      last = now;
      frame = requestAnimationFrame(tick);
    });
    return () => cancelAnimationFrame(frame);
  },
};

export interface SpringFollower {
  /** Chase a new target from wherever the value is now, keeping its velocity. */
  set: (target: number) => void;
  /** Move to a value instantly, with no motion. */
  jump: (value: number) => void;
  get: () => number;
  destroy: () => void;
}

/**
 * A value that follows its target through a spring, integrating the same
 * equation of motion Motion's `useSpring` solves — so a pointer-driven spring
 * reads the same in every build. Runs only while moving; `onUpdate` receives
 * each new value.
 */
export function createSpringFollower(
  initial: number,
  onUpdate: (value: number) => void,
  options: SpringOptions & { restSpeed?: number; ticker?: FrameTicker } = {},
): SpringFollower {
  const { stiffness = 100, damping = 10, mass = 1, ticker = rafTicker } = options;
  const restDelta = options.restDelta ?? 0.01;
  const restSpeed = options.restSpeed ?? 0.01;
  let value = initial;
  let target = initial;
  let velocity = 0;
  let stop: (() => void) | null = null;

  const step = (deltaMs: number) => {
    // Fixed 1ms sub-steps keep the integration stable for stiff springs and
    // independent of the frame rate.
    const steps = Math.min(Math.max(Math.round(deltaMs), 1), 250);
    for (let i = 0; i < steps; i++) {
      const force = -stiffness * (value - target) - damping * velocity;
      velocity += (force / mass) * 0.001;
      value += velocity * 0.001;
    }
    if (Math.abs(target - value) < restDelta && Math.abs(velocity) < restSpeed) {
      value = target;
      velocity = 0;
      stop?.();
      stop = null;
    }
    onUpdate(value);
  };

  return {
    set(next) {
      target = next;
      if (!stop && value !== target) stop = ticker.add(step);
    },
    jump(next) {
      stop?.();
      stop = null;
      value = target = next;
      velocity = 0;
      onUpdate(value);
    },
    get: () => value,
    destroy() {
      stop?.();
      stop = null;
    },
  };
}
